            key2 = key + (r.get("arxiv_id") or "x").replace(".", "")[-4:]
            entry = entry.replace("{" + key + ",", "{" + key2 + ",", 1)
            key = key2
        seen.add(key)
        entries.append(entry)
    os.makedirs(os.path.dirname(out_path) or ".", exist_ok=True)

